  v.scientific_name, v.gbif_key, v.canonical_name,
  v.vernacular_name, v.vernacular_name_en,
  v.kingdom, v.phylum, v.class, v."order", v.family, v.genus,
  private.animal_group_for(v.class, v.phylum),
